package io.tradeops.importer;
import java.math.BigDecimal;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.LocalDate;import java.sql.Statement;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.support.GeneratedKeyHolder;import org.springframework.jdbc.support.KeyHolder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class TransactionImportService { private final JdbcTemplate jdbc; public TransactionImportService(JdbcTemplate jdbc){this.jdbc=jdbc;}
 @Transactional public Summary importCsv(String fileName,byte[] bytes,String actor,String correlationId){String checksum=sha(bytes); if(Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from import_runs where file_checksum=?)",Boolean.class,checksum))) return new Summary(null,"FAILED",0,0,0,"DUPLICATE_FILE",correlationId); KeyHolder keyHolder=new GeneratedKeyHolder();jdbc.update(connection->{var statement=connection.prepareStatement("insert into import_runs(file_name,file_checksum,status,correlation_id,actor_username,started_at) values(?,?, 'RUNNING',?,?,current_timestamp)",Statement.RETURN_GENERATED_KEYS);statement.setString(1,fileName);statement.setString(2,checksum);statement.setString(3,correlationId);statement.setString(4,actor);return statement;},keyHolder);Long runId=Objects.requireNonNull(keyHolder.getKey()).longValue();int accepted=0,rejected=0,duplicate=0;Set<String> seen=new HashSet<>();try{List<String> lines=new String(bytes,StandardCharsets.UTF_8).lines().filter(x->!x.isBlank()).toList();if(lines.size()<2||!lines.get(0).equals("transactionId,transactionDate,counterpartyName,countryCode,amountUsd,currency,dataOrigin"))throw new ImportException("CSV_HEADER_INVALID");for(int i=1;i<lines.size();i++){int row=i+1;try{String[] v=lines.get(i).split(",",-1);if(v.length!=7)throw new ImportException("CSV_ROW_INVALID");String id=v[0].trim();if(!id.matches("[A-Za-z0-9-]{3,100}"))throw new ImportException("INVALID_TRANSACTION_ID");if(!seen.add(id)||Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from trade_transactions where transaction_id=?)",Boolean.class,id))){duplicate++;jdbc.update("insert into import_row_rejections(import_run_id,row_number,error_code,field_name) values(?,?,?,?)",runId,row,"DUPLICATE_TRANSACTION_ID","transactionId");continue;}LocalDate date=LocalDate.parse(v[1]);String name=v[2].trim();if(name.isBlank()||name.length()>255)throw new ImportException("INVALID_COUNTERPARTY_NAME");String country=v[3].trim();if(!country.isEmpty()&&!country.matches("[A-Z]{2}"))throw new ImportException("INVALID_COUNTRY_CODE");BigDecimal amount=new BigDecimal(v[4]);if(amount.signum()<=0||amount.scale()>2)throw new ImportException("INVALID_AMOUNT");String currency=v[5].trim();if(!currency.matches("[A-Z]{3}"))throw new ImportException("INVALID_CURRENCY");if(!"FICTIONAL".equals(v[6].trim()))throw new ImportException("UNSUPPORTED_DATA_ORIGIN");jdbc.update("insert into trade_transactions(import_run_id,transaction_id,transaction_date,counterparty_name,country_code,amount_usd,currency,data_origin) values(?,?,?,?,?,?,?,?)",runId,id,date,name,country.isEmpty()?null:country,amount,currency,"FICTIONAL");accepted++;}catch(Exception e){String code=e instanceof ImportException ie?ie.code:"INVALID_ROW";rejected++;jdbc.update("insert into import_row_rejections(import_run_id,row_number,error_code,field_name) values(?,?,?,?)",runId,row,code,null);}}String status=(rejected+duplicate)>0?"COMPLETED_WITH_ERRORS":"COMPLETED";jdbc.update("update import_runs set status=?,completed_at=current_timestamp,accepted_count=?,rejected_count=?,duplicate_count=? where id=?",status,accepted,rejected,duplicate,runId);return new Summary(runId,status,accepted,rejected,duplicate,null,correlationId);}catch(ImportException e){jdbc.update("update import_runs set status='FAILED',completed_at=current_timestamp where id=?",runId);return new Summary(runId,"FAILED",0,0,0,e.code,correlationId);}}
 private String sha(byte[] b){try{return java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}catch(Exception e){throw new IllegalStateException(e);}} private static class ImportException extends RuntimeException{String code;ImportException(String c){code=c;}} public record Summary(Long runId,String status,int acceptedCount,int rejectedCount,int duplicateCount,String safeErrorCode,String correlationId){}
}